Lemma msteps_cat_lib : forall ms ms', CatSim.msteps BSEGS2 ms ms' -> Exec.msteps bsegs ms ms'.
Proof.
  intros ms ms' H. induction H as [ms | ms ms1 ms2 Hsvc Hstep Hms IH].
  - apply Exec.msteps_refl.
  - eapply Exec.msteps_cons; [split; [exact Hsvc | exact Hstep] | exact IH].
Qed.

