Lemma find_segment_bsegs' : forall (x : Z),
  find_segment bsegs x 1 =
    if ((0x10000 <=? x) && (x + 1 <=? 0x4e000))%Z then Some AsanUbsan.AsanUbsan_segment_000
    else if ((0x4e000 <=? x) && (x + 1 <=? 0x119000))%Z then Some AsanUbsan.AsanUbsan_segment_001
    else if ((0x119000 <=? x) && (x + 1 <=? 0x121000))%Z then Some AsanUbsan.AsanUbsan_segment_002
    else if ((0x121000 <=? x) && (x + 1 <=? 0x684000))%Z then Some AsanUbsan.AsanUbsan_segment_003
    else None.
Proof. intros x. reflexivity. Qed.

Lemma ro_addr_true : forall (a : word), 0x10000 <= bv_unsigned a < 0x119000 -> ro_addr bsegs a = true.
Proof.
  intros a Ha. unfold ro_addr. rewrite find_segment_bsegs'.
  destruct (Z.leb_spec 0x10000 (bv_unsigned a)); destruct (Z.leb_spec (bv_unsigned a + 1) 0x4e000); cbn [andb]; [reflexivity| | lia | lia].
  destruct (Z.leb_spec 0x4e000 (bv_unsigned a)); destruct (Z.leb_spec (bv_unsigned a + 1) 0x119000); cbn [andb]; [reflexivity| lia | lia | lia].
Qed.

