Lemma outside_of_disjoint : forall (x : word) (rs : list (word * Z)),
  (forall r, In r rs -> bv_unsigned x < bv_unsigned (fst r) \/ bv_unsigned (fst r) + snd r <= bv_unsigned x) ->
  OSSVerify.Proofs.boost_beast.http_request.lib.Frame.outside x rs.
Proof.
  intros x rs H. induction rs as [|[r n] rs IH]; [exact I|]. cbn. split.
  - pose proof (H (r, n) (or_introl eq_refl)) as H1. cbn [fst snd] in H1. unfold in_rng. lia.
  - apply IH. intros r' Hr'. apply H. right. exact Hr'.
Qed.

Lemma rdn_frame : forall m m' rs (a : word) n bs,
  frame_mod m m' rs -> rdn BSEGS2 m a n = Some bs -> bv_unsigned a + Z.of_nat n <= 2 ^ 64 ->
  (forall r, In r rs -> bv_unsigned a + Z.of_nat n <= bv_unsigned (fst r) \/ bv_unsigned (fst r) + snd r <= bv_unsigned a) ->
  rdn BSEGS2 m' a n = Some bs.
Proof.
  intros m m' rs a n bs [Hout _] Hr Hnw Hd. rewrite (rdn_ext BSEGS2 n m' m a); [exact Hr | exact Hnw |].
  intros x Hx. apply Hout. apply outside_of_disjoint. intros r0 Hr0. pose proof (Hd r0 Hr0). lia.
Qed.

Lemma rdn_S : forall m (a : word) n bs,
  rdn BSEGS2 m a (S n) = Some bs ->
  exists b r, bs = b :: r /\ mrd bsegs m a = Some b /\ rdn BSEGS2 m (a + 1)%bv n = Some r.
Proof.
  intros m a n bs H. change (rdn BSEGS2) with (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.PropExec.rdn bsegs) in H |- *.
  rewrite rdn_unfold in H. destruct (mrd bsegs m a) as [b|]; [|discriminate].
  destruct (OSSVerify.Proofs.boost_beast.http_request.lib.Lib.PropExec.rdn bsegs m (a + 1)%bv n) as [r|]; [|discriminate].
  injection H as <-. exists b, r. auto.
Qed.
