(* [comment removed for export] *)
Lemma bytes_at_rdn_all : forall m (a : Z) bs,
  bytes_at bsegs m a bs -> rdn BSEGS2 m (Z_to_bv 64 a) (length bs) = Some bs.
Proof.
  intros m a bs H. pose proof (Mem.bytes_at_rdn bsegs m a bs 0 (length bs) H ltac:(cbn; lia)) as R.
  cbn [Z.of_nat skipn] in R. rewrite Z.add_0_r, firstn_all in R. rewrite <- wa_eq. exact R.
Qed.

