(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma seg_rom_high : forall (a : word), (0x684000 <= bv_unsigned a)%Z -> seg_rom BSEGS2 a = None.
Proof.
  intros a Ha. unfold seg_rom. unfold memory_read.
  cbn -[bv_unsigned Z.leb Z.ltb Z.add Z.sub N.leb N.ltb N.add bv_extract Z.of_N Z.to_N].
  cbn [Z.of_N].
  repeat (lazymatch goal with
          | |- context [((?lo <=? bv_unsigned a)%Z && ?c)%bool] =>
              replace c with false by (symmetry; apply Z.leb_gt; lia); rewrite andb_false_r
          end).
  reflexivity.
Qed.

(* [comment removed for export] *)
Lemma stk_grows : forall m m' l h, stk bsegs m l h -> 0x684000 <= l -> mem_grows m m' -> stk bsegs m' l h.
Proof.
  intros m m' l h (S1 & S2 & S3) Hl Hg. split; [exact S1|]. split; [exact S2|].
  intros x Hx. destruct (S3 x Hx) as [Hw [b Hb]].
  assert (E0 : exists b0, m (wa x) = Some b0).
  { unfold mrd in Hb. destruct (m (wa x)) as [b0|] eqn:E; [exists b0; reflexivity|].
    rewrite seg_rom_same in Hb. change bsegs with BSEGS2 in Hb.
    rewrite seg_rom_high in Hb; [discriminate|]. rewrite wa_eq, u_small by lia. lia. }
  destruct E0 as [b0 E0].
  assert (E1 : exists b1, m' (wa x) = Some b1).
  { destruct (m' (wa x)) as [b1|] eqn:E; [exists b1; reflexivity|]. exfalso. apply (Hg (wa x)); congruence. }
  destruct E1 as [b1 E1]. split.
  - unfold wview. rewrite E1. discriminate.
  - exists b1. unfold mrd. rewrite E1. reflexivity.
Qed.

Lemma frame_mod_stk : forall m m' rs l h, stk bsegs m l h -> 0x684000 <= l -> frame_mod m m' rs -> stk bsegs m' l h.
Proof. intros m m' rs l h S Hl [_ Hg]. eapply stk_grows; eassumption. Qed.

(* [comment removed for export] *)
Lemma wr_at_wmono : forall m m' A n, wr_at bsegs m A n -> wmono bsegs m m' -> wr_at bsegs m' A n.
Proof. intros m m' A n (H1 & H2 & H) W. split; [lia|]. split; [lia|]. intros i Hi. apply W. apply H. exact Hi. Qed.

