Definition rshape (R : bvmap 5 word) : Prop :=
  R = mkR (getr R 1) (getr R 2) (getr R 3) (getr R 4) (getr R 5) (getr R 6) (getr R 7) (getr R 8)
          (getr R 9) (getr R 10) (getr R 11) (getr R 12) (getr R 13) (getr R 14) (getr R 15) (getr R 16)
          (getr R 17) (getr R 18) (getr R 19) (getr R 20) (getr R 21) (getr R 22) (getr R 23) (getr R 24)
          (getr R 25) (getr R 26) (getr R 27) (getr R 28) (getr R 29) (getr R 30) (getr R 31).

Lemma rshape_mkR : forall x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31,
  rshape (mkR x1 x2 x3 x4 x5 x6 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31).
Proof. intros. reflexivity. Qed.

Lemma bv5_cases : forall (P : bv 5 -> Prop),
  (forall k, (0 <= k < 32)%Z -> P (Z_to_bv 5 k)) -> forall r, P r.
Proof.
  intros P H r. pose proof (bv_unsigned_in_range 5 r) as Hr. unfold bv_modulus in Hr. cbn in Hr.
  replace r with (Z_to_bv 5 (bv_unsigned r)) by (apply bv_eq; rewrite Z_to_bv_unsigned; unfold bv_wrap, bv_modulus; cbn; rewrite Z.mod_small by lia; reflexivity).
  apply H. lia.
Qed.

